import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Validates successful user registration workflow including email validation,
 * password hashing, and immediate token generation.
 *
 * This test ensures that new users can register with valid credentials and
 * receive JWT tokens for immediate authentication. It verifies account status
 * assignment as 'pending_verification' and ensures all required fields are
 * properly validated and stored.
 */
export async function test_api_user_registration_success(
  connection: api.IConnection,
) {
  // Generate realistic test data for user registration
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userName = RandomGenerator.name();

  // Create registration request body with all required fields
  const registrationData = {
    email: userEmail,
    password: "SecurePassword123!",
    name: userName,
    ip: typia.random<string & tags.Format<"ipv4">>(),
    href: "https://todoapp.example.com/register",
    referrer: "https://todoapp.example.com",
  } satisfies ITodoAppUser.ICreate;

  // Execute user registration API call
  const registeredUser = await api.functional.auth.user.join(connection, {
    body: registrationData,
  });

  // Validate response type safety and structure
  typia.assert(registeredUser);

  // Verify user information matches registration data
  TestValidator.equals(
    "email should match registration input",
    registeredUser.email,
    userEmail,
  );
  TestValidator.equals(
    "name should match registration input",
    registeredUser.name,
    userName,
  );

  // Validate account status defaults to 'pending_verification'
  TestValidator.equals(
    "account status should be pending_verification",
    registeredUser.status,
    "pending_verification",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test registration failure when attempting to register with an email that
 * already exists in the system. Validates email uniqueness constraint
 * enforcement and appropriate error messaging to prevent duplicate account
 * creation.
 */
export async function test_api_user_registration_duplicate_email(
  connection: api.IConnection,
) {
  // Generate a unique email address for testing
  const email = typia.random<string & tags.Format<"email">>();

  // Create first user registration with valid data
  const firstUser = await api.functional.auth.user.join(connection, {
    body: {
      email: email,
      password: "TestPassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(firstUser);

  // Verify first registration was successful
  TestValidator.equals("first user email matches", firstUser.email, email);
  TestValidator.predicate(
    "first user has valid token",
    firstUser.token.access.length > 0,
  );

  // Attempt to register second user with the same email address
  await TestValidator.error(
    "duplicate email registration should fail",
    async () => {
      return await api.functional.auth.user.join(connection, {
        body: {
          email: email,
          password: "AnotherPassword456",
          name: RandomGenerator.name(),
          href: "https://example.com/register",
          referrer: "https://example.com",
        } satisfies ITodoAppUser.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test registration failure scenarios with valid email formats. Validates
 * business logic errors rather than type validation.
 */
export async function test_api_user_registration_invalid_email_format(
  connection: api.IConnection,
) {
  // Create a valid user first to test duplicate email scenario
  const validEmail = typia.random<string & tags.Format<"email">>();

  const validUser = await api.functional.auth.user.join(connection, {
    body: {
      email: validEmail,
      password: "ValidPassword123!",
      name: RandomGenerator.name(),
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(validUser);

  // Test duplicate email registration - this should fail due to business logic
  await TestValidator.error(
    "registration should fail with duplicate email",
    async () => {
      await api.functional.auth.user.join(connection, {
        body: {
          email: validEmail, // Same email as existing user
          password: "DifferentPassword456!",
          name: RandomGenerator.name(),
          href: "https://example.com/register",
          referrer: "https://example.com",
        } satisfies ITodoAppUser.ICreate,
      });
    },
  );

  // Test with another valid email to ensure the API works correctly
  const anotherValidEmail = typia.random<string & tags.Format<"email">>();
  const anotherUser = await api.functional.auth.user.join(connection, {
    body: {
      email: anotherValidEmail,
      password: "AnotherPassword789!",
      name: RandomGenerator.name(),
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(anotherUser);

  // Verify both users were created successfully
  TestValidator.equals("first user email matches", validUser.email, validEmail);
  TestValidator.equals(
    "second user email matches",
    anotherUser.email,
    anotherValidEmail,
  );
  TestValidator.notEquals(
    "user IDs should be different",
    validUser.id,
    anotherUser.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Validates user registration functionality with comprehensive field
 * validation.
 *
 * This test ensures the API properly handles user registration requests with
 * valid data, including both required and optional fields. It focuses on
 * successful registration scenarios rather than testing type system
 * violations.
 */
export async function test_api_user_registration_missing_required_fields(
  connection: api.IConnection,
) {
  // Generate valid test data for registration
  const validEmail = typia.random<string & tags.Format<"email">>();
  const validPassword = RandomGenerator.alphaNumeric(12);
  const validName = RandomGenerator.name();
  const validHref = typia.random<string & tags.Format<"uri">>();
  const validReferrer = typia.random<string & tags.Format<"uri">>();

  // Test successful registration with all required fields
  const userWithRequiredFields = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: validEmail,
        password: validPassword,
        name: validName,
        href: validHref,
        referrer: validReferrer,
      } satisfies ITodoAppUser.ICreate,
    },
  );
  typia.assert(userWithRequiredFields);
  TestValidator.equals(
    "user should have correct email",
    userWithRequiredFields.email,
    validEmail,
  );
  TestValidator.equals(
    "user should have correct name",
    userWithRequiredFields.name,
    validName,
  );

  // Test successful registration with all fields including optional ones
  const userWithAllFields = await api.functional.auth.user.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      status: "active",
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(userWithAllFields);

  // Test successful registration with only required fields and optional status
  const userWithStatus = await api.functional.auth.user.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      status: "pending_verification",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(userWithStatus);

  // Test successful registration with only required fields and optional ip
  const userWithIp = await api.functional.auth.user.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(userWithIp);

  // Validate that all created users have proper token information
  const users = [
    userWithRequiredFields,
    userWithAllFields,
    userWithStatus,
    userWithIp,
  ];
  for (const user of users) {
    TestValidator.predicate(
      "user should have access token",
      user.token.access.length > 0,
    );
    TestValidator.predicate(
      "user should have refresh token",
      user.token.refresh.length > 0,
    );
    TestValidator.predicate(
      "user should have expiration date",
      user.token.expired_at.length > 0,
    );
    TestValidator.predicate(
      "user should have refreshable until date",
      user.token.refreshable_until.length > 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test successful user login with valid credentials.
 *
 * This E2E test validates the complete authentication workflow by first
 * creating a user account and then testing login functionality. It verifies
 * password comparison against stored hash, proper JWT token generation, and
 * account status validation that allows 'pending_verification' accounts to
 * authenticate.
 *
 * The test ensures that the login endpoint correctly handles session context
 * information and returns comprehensive user data with authentication tokens.
 */
export async function test_api_user_login_success(connection: api.IConnection) {
  // Step 1: Create a user account for login testing
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "TestPassword123";
  const userName = RandomGenerator.name();

  const createdUser = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      name: userName,
      status: "pending_verification",
      href: "https://todoapp.com/login" satisfies string as string,
      referrer: "https://todoapp.com/" satisfies string as string,
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(createdUser);

  // Step 2: Test successful login with valid credentials
  const loginResponse = await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      href: "https://todoapp.com/dashboard" satisfies string as string,
      referrer: "https://todoapp.com/login" satisfies string as string,
    } satisfies ITodoAppUser.ILogin,
  });
  typia.assert(loginResponse);

  // Step 3: Validate login response structure and data
  TestValidator.equals(
    "user ID should match created user",
    loginResponse.id,
    createdUser.id,
  );
  TestValidator.equals(
    "user email should match",
    loginResponse.email,
    userEmail,
  );
  TestValidator.equals("user name should match", loginResponse.name, userName);
  TestValidator.equals(
    "user status should be pending_verification",
    loginResponse.status,
    "pending_verification",
  );

  // Step 4: Validate token generation
  TestValidator.predicate(
    "access token should be generated",
    loginResponse.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token should be generated",
    loginResponse.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "token expiration should be valid",
    new Date(loginResponse.token.expired_at) > new Date(),
  );
  TestValidator.predicate(
    "refresh token expiration should be valid",
    new Date(loginResponse.token.refreshable_until) > new Date(),
  );

  // Step 5: Validate timestamps
  TestValidator.predicate(
    "created_at timestamp should be valid",
    new Date(loginResponse.created_at) <= new Date(),
  );
  TestValidator.predicate(
    "updated_at timestamp should be valid",
    new Date(loginResponse.updated_at) <= new Date(),
  );

  // Step 6: Validate last_login_at is updated (should be more recent than created_at)
  if (loginResponse.last_login_at) {
    TestValidator.predicate(
      "last_login_at should be after account creation",
      new Date(loginResponse.last_login_at) >=
        new Date(loginResponse.created_at),
    );
  }
}

