/**
 * Test user authentication workflow and session token generation. Validates
 * that users can create accounts and authenticate successfully, receiving
 * proper JWT tokens for session management. This test focuses on the
 * authentication aspects that can be validated with the available API
 * functions.
 */
export async function test_api_user_session_management_deletion(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account for authentication testing
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "TestPassword123";
  const userName = RandomGenerator.name();

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      name: userName,
      href: "https://todoapp.example.com/register",
      referrer: "https://todoapp.example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Validate user creation response
  TestValidator.equals(
    "user ID should be a valid UUID",
    user.id,
    typia.assert<string & tags.Format<"uuid">>(user.id),
  );
  TestValidator.equals("user email should match input", user.email, userEmail);
  TestValidator.equals("user name should match input", user.name, userName);
  TestValidator.predicate(
    "user should have authentication token",
    user.token !== undefined,
  );
  TestValidator.predicate(
    "token should have access property",
    user.token.access.length > 0,
  );
  TestValidator.predicate(
    "token should have refresh property",
    user.token.refresh.length > 0,
  );

  // Step 2: Authenticate the user to validate login functionality
  const authenticatedUser = await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      href: "https://todoapp.example.com/login",
      referrer: "https://todoapp.example.com",
    } satisfies ITodoAppUser.ILogin,
  });
  typia.assert(authenticatedUser);

  // Validate authentication response
  TestValidator.equals(
    "authenticated user ID should match created user",
    authenticatedUser.id,
    user.id,
  );
  TestValidator.equals(
    "authenticated user email should match",
    authenticatedUser.email,
    userEmail,
  );
  TestValidator.predicate(
    "authenticated user should have new token",
    authenticatedUser.token !== undefined,
  );
  TestValidator.notEquals(
    "login should generate new access token",
    authenticatedUser.token.access,
    user.token.access,
  );

  // Note: Session deletion functionality cannot be tested with available APIs
  // as there is no way to obtain valid session IDs for deletion
  TestValidator.predicate(
    "authentication workflow completed successfully",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test complete todo lifecycle from creation to retrieval.
 *
 * Validates that todos can be properly created and retrieved with all fields
 * intact, including text content, completion status, and timestamps. This test
 * ensures the API endpoints maintain data integrity throughout the todo
 * lifecycle.
 */
export async function test_api_todo_retrieval_by_id(
  connection: api.IConnection,
) {
  // Step 1: Create user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "testPassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/todo-app",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create a todo item
  const todoText = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 3,
    wordMax: 8,
  });
  const todo = await api.functional.todoApp.user.todos.create(connection, {
    body: {
      text: todoText,
      completed: false,
    } satisfies ITodoAppTodo.ICreate,
  });
  typia.assert(todo);

  // Step 3: Retrieve the todo by ID
  const retrievedTodo = await api.functional.todoApp.user.todos.at(connection, {
    todoId: todo.id,
  });
  typia.assert(retrievedTodo);

  // Step 4: Validate that retrieved todo matches created todo
  TestValidator.equals("todo ID matches", retrievedTodo.id, todo.id);
  TestValidator.equals("todo text matches", retrievedTodo.text, todo.text);
  TestValidator.equals(
    "completion status matches",
    retrievedTodo.completed,
    todo.completed,
  );
  TestValidator.equals(
    "created timestamp matches",
    retrievedTodo.created_at,
    todo.created_at,
  );
  TestValidator.equals(
    "updated timestamp matches",
    retrievedTodo.updated_at,
    todo.updated_at,
  );

  // Step 5: Validate business logic
  TestValidator.predicate(
    "todo text meets length requirements",
    todoText.length >= 1 && todoText.length <= 500,
  );
  TestValidator.predicate(
    "created timestamp is valid ISO string",
    !isNaN(new Date(todo.created_at).getTime()),
  );
  TestValidator.predicate(
    "updated timestamp is valid ISO string",
    !isNaN(new Date(todo.updated_at).getTime()),
  );
}

