 * completion status (completed=true) during creation. The test follows a
 * complete workflow: user authentication followed by todo creation with
 * explicit completion status validation.
 */
export async function test_api_todo_creation_with_completion_status(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate a user
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "testPassword123";

  const user = await api.functional.auth.user.join(connection, {
