import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppConfiguration";
import type { ITodoAppConfigurationValue } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppConfigurationValue";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test updating an environment-specific configuration value by an authenticated
 * user.
 *
 * This test validates the complete workflow of configuration value management:
 *
 * 1. User authentication and authorization setup
 * 2. Configuration definition creation
 * 3. Environment-specific value creation and updates
 * 4. Value type and active status modifications
 * 5. Referential integrity validation
 * 6. Timestamp tracking verification
 */
export async function test_api_configuration_value_update_by_user(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate a user
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "testPassword123";
  const userName = RandomGenerator.name();

  const user: ITodoAppUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: userEmail,
        password: userPassword,
        name: userName,
        href: "https://example.com/test",
        referrer: "https://example.com",
      } satisfies ITodoAppUser.ICreate,
    },
  );
  typia.assert(user);

  // Step 2: Create a configuration definition
  const configKey = `test.${RandomGenerator.alphaNumeric(8)}.setting`;
  const configName = RandomGenerator.paragraph({ sentences: 3 });
  const configDescription = RandomGenerator.content({ paragraphs: 1 });

  const configuration: ITodoAppConfiguration =
    await api.functional.todoApp.user.configurations.create(connection, {
      body: {
        config_key: configKey,
        name: configName,
        description: configDescription,
        data_type: "string",
        default_value: "default_value",
        validation_rules: null,
        category: "test",
        is_sensitive: false,
        is_required: false,
      } satisfies ITodoAppConfiguration.ICreate,
    });
  typia.assert(configuration);

  // Step 3: Create initial configuration value for development environment
  const initialConfigValue: ITodoAppConfigurationValue =
    await api.functional.todoApp.user.configurations.values.update(connection, {
      configKey: configKey,
      environment: "development",
      body: {
        config_value: "initial_value",
        value_type: "string",
        is_active: true,
      } satisfies ITodoAppConfigurationValue.IUpdate,
    });
  typia.assert(initialConfigValue);

  // Step 4: Update configuration value - modify the value
  const updatedValue: ITodoAppConfigurationValue =
    await api.functional.todoApp.user.configurations.values.update(connection, {
      configKey: configKey,
      environment: "development",
      body: {
        config_value: "updated_value",
      } satisfies ITodoAppConfigurationValue.IUpdate,
    });
  typia.assert(updatedValue);

  // Validate that the value was updated
  TestValidator.equals(
    "config value should be updated",
    updatedValue.config_value,
    "updated_value",
  );
  TestValidator.equals(
    "value type should remain unchanged",
    updatedValue.value_type,
    "string",
  );
  TestValidator.equals(
    "active status should remain unchanged",
    updatedValue.is_active,
    true,
  );

  // Step 5: Update configuration value - change value type
  const typeUpdatedValue: ITodoAppConfigurationValue =
    await api.functional.todoApp.user.configurations.values.update(connection, {
      configKey: configKey,
      environment: "development",
      body: {
        value_type: "json",
      } satisfies ITodoAppConfigurationValue.IUpdate,
    });
  typia.assert(typeUpdatedValue);

  // Validate that the value type was updated
  TestValidator.equals(
    "value type should be updated to json",
    typeUpdatedValue.value_type,
    "json",
  );
  TestValidator.equals(
    "config value should remain unchanged",
    typeUpdatedValue.config_value,
    "updated_value",
  );

  // Step 6: Update configuration value - toggle active status
  const statusUpdatedValue: ITodoAppConfigurationValue =
    await api.functional.todoApp.user.configurations.values.update(connection, {
      configKey: configKey,
      environment: "development",
      body: {
        is_active: false,
      } satisfies ITodoAppConfigurationValue.IUpdate,
    });
  typia.assert(statusUpdatedValue);

  // Validate that the active status was updated
  TestValidator.equals(
    "active status should be updated to false",
    statusUpdatedValue.is_active,
    false,
  );
  TestValidator.equals(
    "config value should remain unchanged",
    statusUpdatedValue.config_value,
    "updated_value",
  );
  TestValidator.equals(
    "value type should remain unchanged",
    statusUpdatedValue.value_type,
    "json",
  );

  // Step 7: Verify timestamp tracking
  TestValidator.predicate(
    "updated_at should be after created_at",
    new Date(statusUpdatedValue.updated_at) >
      new Date(statusUpdatedValue.created_at),
  );

  // Step 8: Create configuration value for different environment
  const productionValue: ITodoAppConfigurationValue =
    await api.functional.todoApp.user.configurations.values.update(connection, {
      configKey: configKey,
      environment: "production",
      body: {
        config_value: "production_value",
        value_type: "string",
        is_active: true,
      } satisfies ITodoAppConfigurationValue.IUpdate,
    });
  typia.assert(productionValue);

  // Validate environment-specific values are independent
  TestValidator.notEquals(
    "development and production values should be different",
    statusUpdatedValue.config_value,
    productionValue.config_value,
  );
  TestValidator.notEquals(
    "development and production environments should be different",
    statusUpdatedValue.environment,
    productionValue.environment,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppConfigurationValue } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppConfigurationValue";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test soft deletion of an environment-specific configuration value by an
 * authenticated user.
 *
 * This test validates the configuration value deletion endpoint. Since the
 * provided API functions don't include a way to create configuration values,
 * this test focuses on validating the deletion operation's behavior with
 * various input scenarios.
 */
export async function test_api_configuration_value_deletion_by_user(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate a user
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "testPassword123";

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      name: RandomGenerator.name(),
      href: "https://example.com/todo-app",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Test deletion with valid but likely non-existent configuration
  // Since we can't create configuration values, test the API contract
  const configKey = RandomGenerator.alphaNumeric(10);
  const environment = RandomGenerator.pick([
    "development",
    "staging",
    "production",
  ] as const);

  const deletedValue =
    await api.functional.todoApp.user.configurations.values.erase(connection, {
      configKey: configKey,
      environment: environment,
    });
  typia.assert(deletedValue);

  // Validate the response structure matches ITodoAppConfigurationValue
  TestValidator.equals(
    "response should have environment field",
    deletedValue.environment,
    environment,
  );
  TestValidator.predicate(
    "response should have valid UUID id",
    /^[0-9a-f-]{36}$/i.test(deletedValue.id),
  );
  TestValidator.predicate(
    "response should have config_value field",
    typeof deletedValue.config_value === "string",
  );
  TestValidator.predicate(
    "response should have value_type field",
    typeof deletedValue.value_type === "string",
  );
  TestValidator.predicate(
    "response should have is_active field",
    typeof deletedValue.is_active === "boolean",
  );
  TestValidator.predicate(
    "response should have created_at timestamp",
    typeof deletedValue.created_at === "string",
  );
  TestValidator.predicate(
    "response should have updated_at timestamp",
    typeof deletedValue.updated_at === "string",
  );

  // Step 3: Test error scenario with invalid configuration key
  await TestValidator.error(
    "should handle invalid configuration key format",
    async () => {
      await api.functional.todoApp.user.configurations.values.erase(
        connection,
        {
          configKey: "", // Empty config key should trigger validation error
          environment: environment,
        },
      );
    },
  );

  // Step 4: Test error scenario with invalid environment
  await TestValidator.error(
    "should handle invalid environment format",
    async () => {
      await api.functional.todoApp.user.configurations.values.erase(
        connection,
        {
          configKey: configKey,
          environment: "", // Empty environment should trigger validation error
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppConfiguration";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test creation of a new todo application configuration definition by an
 * authenticated user.
 *
 * This test validates that authenticated users can successfully create
 * configuration definitions with proper metadata including unique configuration
 * keys, human-readable names, detailed descriptions, data type specifications,
 * default values, and validation rules. The test ensures that configuration key
 * uniqueness is enforced across the system and that data type compatibility is
 * maintained between default values and validation rules.
 */
export async function test_api_configuration_creation_by_user(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as a user to establish authorization context
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "testPassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/todo-app",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create a configuration with valid metadata
  const configurationData = {
    config_key: `test.config.${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({ paragraphs: 2 }),
    data_type: "string",
    default_value: "default configuration value",
    validation_rules: JSON.stringify({ minLength: 5, maxLength: 100 }),
    category: "test",
    is_sensitive: false,
    is_required: true,
  } satisfies ITodoAppConfiguration.ICreate;

  const configuration = await api.functional.todoApp.user.configurations.create(
    connection,
    { body: configurationData },
  );
  typia.assert(configuration);

  // Step 3: Validate the response contains all expected fields with correct values
  TestValidator.equals(
    "config_key should match input",
    configuration.config_key,
    configurationData.config_key,
  );
  TestValidator.equals(
    "name should match input",
    configuration.name,
    configurationData.name,
  );
  TestValidator.equals(
    "description should match input",
    configuration.description,
    configurationData.description,
  );
  TestValidator.equals(
    "data_type should match input",
    configuration.data_type,
    configurationData.data_type,
  );
  TestValidator.equals(
    "default_value should match input",
    configuration.default_value,
    configurationData.default_value,
  );
  TestValidator.equals(
    "category should match input",
    configuration.category,
    configurationData.category,
  );
  TestValidator.equals(
    "is_sensitive should match input",
    configuration.is_sensitive,
    configurationData.is_sensitive,
  );
  TestValidator.equals(
    "is_required should match input",
    configuration.is_required,
    configurationData.is_required,
  );
  TestValidator.predicate(
    "version should be positive number",
    configuration.version > 0,
  );

  // Step 4: Test business rule - configuration key uniqueness
  await TestValidator.error("duplicate config_key should fail", async () => {
    await api.functional.todoApp.user.configurations.create(connection, {
      body: {
        ...configurationData,
        name: "Different name for duplicate test",
      } satisfies ITodoAppConfiguration.ICreate,
    });
  });

  // Step 5: Test data type compatibility with different data types
  const booleanConfig = await api.functional.todoApp.user.configurations.create(
    connection,
    {
      body: {
        config_key: `test.boolean.${RandomGenerator.alphaNumeric(8)}`,
        name: "Boolean configuration test",
        description: "A configuration with boolean data type",
        data_type: "boolean",
        default_value: "true",
        validation_rules: null,
        category: "test",
        is_sensitive: false,
        is_required: false,
      } satisfies ITodoAppConfiguration.ICreate,
    },
  );
  typia.assert(booleanConfig);

  const numberConfig = await api.functional.todoApp.user.configurations.create(
    connection,
    {
      body: {
        config_key: `test.number.${RandomGenerator.alphaNumeric(8)}`,
        name: "Number configuration test",
        description: "A configuration with number data type",
        data_type: "number",
        default_value: "42",
        validation_rules: JSON.stringify({ minimum: 0, maximum: 100 }),
        category: "test",
        is_sensitive: true,
        is_required: true,
      } satisfies ITodoAppConfiguration.ICreate,
    },
  );
  typia.assert(numberConfig);

  // Step 6: Verify sensitive and required flags are properly handled
  TestValidator.equals(
    "boolean config is_sensitive should be false",
    booleanConfig.is_sensitive,
    false,
  );
  TestValidator.equals(
    "boolean config is_required should be false",
    booleanConfig.is_required,
    false,
  );
  TestValidator.equals(
    "number config is_sensitive should be true",
    numberConfig.is_sensitive,
    true,
  );
  TestValidator.equals(
    "number config is_required should be true",
    numberConfig.is_required,
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppUserSession";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import type { ITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSession";

/**
 * Test comprehensive session search functionality for authenticated users.
 *
 * This test validates that users can search their own sessions with various
 * filtering options including status-based filtering (active/expired), date
 * range queries (created_after, created_before), and pagination controls. It
 * ensures search results are properly filtered by the authenticated user's
 * email address and that pagination metadata is correctly returned.
 *
 * Test scenarios include:
 *
 * 1. Creating a user account and generating session activity
 * 2. Searching for active sessions
 * 3. Searching for expired sessions
 * 4. Searching sessions within specific date ranges
 * 5. Testing pagination functionality
 * 6. Validating that search results are properly filtered by user email
 * 7. Testing error scenarios and boundary conditions
 */
export async function test_api_user_sessions_search_by_authenticated_user(
  connection: api.IConnection,
) {
  // Step 1: Create authenticated user context
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "TestPassword123!";

  const createdUser = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(createdUser);

  // Step 2: Generate session activity by logging in
  const loginResponse = await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies ITodoAppUser.ILogin,
  });
  typia.assert(loginResponse);

  // Step 3: Test basic session search with pagination
  const basicSearchResult =
    await api.functional.todoApp.user.users.sessions.index(connection, {
      userEmail: userEmail,
      body: {
        page: 1,
        limit: 10,
      } satisfies ITodoAppUserSession.IRequest,
    });
  typia.assert(basicSearchResult);

  TestValidator.equals(
    "pagination metadata should be present",
    basicSearchResult.pagination.current,
    1,
  );
  TestValidator.equals(
    "limit should match request",
    basicSearchResult.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "records count should be non-negative",
    basicSearchResult.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages count should be non-negative",
    basicSearchResult.pagination.pages >= 0,
  );

  // Validate session data structure
  if (basicSearchResult.data.length > 0) {
    const sampleSession = basicSearchResult.data[0];
    TestValidator.predicate(
      "session should have valid UUID id",
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        sampleSession.id,
      ),
    );
    TestValidator.predicate(
      "session should have created_at timestamp",
      sampleSession.created_at.length > 0,
    );
    TestValidator.predicate(
      "session should have last_activity_at timestamp",
      sampleSession.last_activity_at.length > 0,
    );
  }

  // Step 4: Test active sessions filtering
  const activeSessionsResult =
    await api.functional.todoApp.user.users.sessions.index(connection, {
      userEmail: userEmail,
      body: {
        page: 1,
        limit: 10,
        status: "active",
      } satisfies ITodoAppUserSession.IRequest,
    });
  typia.assert(activeSessionsResult);

  // Step 5: Test expired sessions filtering
  const expiredSessionsResult =
    await api.functional.todoApp.user.users.sessions.index(connection, {
      userEmail: userEmail,
      body: {
        page: 1,
        limit: 10,
        status: "expired",
      } satisfies ITodoAppUserSession.IRequest,
    });
  typia.assert(expiredSessionsResult);

  // Step 6: Test date range filtering with dynamic dates
  const currentDate = new Date().toISOString();
  const oneDayAgo = new Date(Date.now() - 86400000).toISOString(); // 1 day ago
  const oneWeekAgo = new Date(Date.now() - 604800000).toISOString(); // 1 week ago

  const recentSessionsResult =
    await api.functional.todoApp.user.users.sessions.index(connection, {
      userEmail: userEmail,
      body: {
        page: 1,
        limit: 10,
        created_after: oneWeekAgo,
        created_before: currentDate,
      } satisfies ITodoAppUserSession.IRequest,
    });
  typia.assert(recentSessionsResult);

  // Step 7: Test free-text search
  const searchTextResult =
    await api.functional.todoApp.user.users.sessions.index(connection, {
      userEmail: userEmail,
      body: {
        page: 1,
        limit: 10,
        search: "test",
      } satisfies ITodoAppUserSession.IRequest,
    });
  typia.assert(searchTextResult);

  // Step 8: Test pagination with different page and limit values
  const paginationTestResult =
    await api.functional.todoApp.user.users.sessions.index(connection, {
      userEmail: userEmail,
      body: {
        page: 2,
        limit: 5,
      } satisfies ITodoAppUserSession.IRequest,
    });
  typia.assert(paginationTestResult);

  TestValidator.equals(
    "page should match request",
    paginationTestResult.pagination.current,
    2,
  );
  TestValidator.equals(
    "limit should match request",
    paginationTestResult.pagination.limit,
    5,
  );

  // Step 9: Test boundary conditions
