  // Step 1: Create a new user account for authentication context
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = RandomGenerator.alphaNumeric(12);

  const createdUser = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(createdUser);

  // Step 2: Create multiple todo items associated with the user account
  const todoCount = typia.random<
    number & tags.Type<"uint32"> & tags.Minimum<2> & tags.Maximum<5>
  >();
  const createdTodos: ITodoAppTodo[] = [];

  for (let i = 0; i < todoCount; i++) {
    const todo = await api.functional.todoApp.user.todos.create(connection, {
      body: {
        text: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 5,
          wordMax: 10,
        }),
        completed: i % 2 === 0,
      } satisfies ITodoAppTodo.ICreate,
    });
    typia.assert(todo);
    createdTodos.push(todo);
  }

  // Step 3: Perform user account deletion
  const deletedUser = await api.functional.todoApp.user.users.erase(
    connection,
    {
      userEmail: userEmail,
    },
  );
  typia.assert(deletedUser);

  // Step 4: Validate user account deletion was successful
  TestValidator.equals(
    "deleted user email matches",
    deletedUser.email,
    userEmail,
  );
  TestValidator.equals(
    "deleted user ID matches",
    deletedUser.id,
    createdUser.id,
  );

  // Step 5: Attempt to access deleted user's todo items to verify cleanup
  // Since the user account is deleted, attempting to create new todos should fail
  await TestValidator.error("cannot create todo for deleted user", async () => {
    await api.functional.todoApp.user.todos.create(connection, {
      body: {
        text: RandomGenerator.paragraph({ sentences: 2 }),
        completed: false,
      } satisfies ITodoAppTodo.ICreate,
    });
  });

  // Additional validation: Test that the user authentication is properly invalidated
  // by attempting to use the original user's context (which should fail)

  // Step 6: Create a new user to verify the system still works for valid users
  const newUserEmail = typia.random<string & tags.Format<"email">>();
  const newUser = await api.functional.auth.user.join(connection, {
    body: {
      email: newUserEmail,
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(newUser);

  // Verify new user can create todos (ensuring authentication is working for valid users)
  const newTodo = await api.functional.todoApp.user.todos.create(connection, {
    body: {
      text: RandomGenerator.paragraph({ sentences: 2 }),
      completed: true,
    } satisfies ITodoAppTodo.ICreate,
  });
  typia.assert(newTodo);

  // Final validation: The system maintains integrity with proper cleanup
  TestValidator.predicate(
    "user account deletion successfully processed and system integrity maintained",
    deletedUser.id !== newUser.id && newTodo.id !== createdTodos[0]?.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Validate security measures during user account deletion operations.
 *
 * This test ensures proper authorization enforcement for account deletion,
 * verifying that users can only delete their own accounts and that security
 * mechanisms prevent unauthorized deletion attempts. The test creates multiple
 * user accounts and validates authentication context switching and proper
 * access control.
 */
export async function test_api_user_account_deletion_security_validation(
  connection: api.IConnection,
) {
  // Create primary user account
  const primaryUserEmail = typia.random<string & tags.Format<"email">>();
  const primaryUser = await api.functional.auth.user.join(connection, {
    body: {
      email: primaryUserEmail,
      password: "password123",
      name: RandomGenerator.name(),
      href: "https://example.com",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(primaryUser);

  // Create secondary user account
  const secondaryUserEmail = typia.random<string & tags.Format<"email">>();
  const secondaryUser = await api.functional.auth.user.join(connection, {
    body: {
      email: secondaryUserEmail,
      password: "password456",
      name: RandomGenerator.name(),
      href: "https://example.com",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(secondaryUser);

  // Attempt unauthorized deletion - secondary user trying to delete primary user's account
  // The SDK automatically uses the latest authentication token (secondary user)
  await TestValidator.error(
    "unauthorized user cannot delete other user's account",
    async () => {
      await api.functional.todoApp.user.users.erase(connection, {
        userEmail: primaryUserEmail,
      });
    },
  );

  // For authorized deletion, we need to re-authenticate as the primary user
  // Since there's no login function, we'll create a fresh connection without authentication
  const unauthConnection: api.IConnection = { ...connection, headers: {} };

  // Re-authenticate as primary user by joining again (which sets the auth token)
  const reauthenticatedPrimaryUser = await api.functional.auth.user.join(
    unauthConnection,
    {
      body: {
        email: primaryUserEmail,
        password: "password123",
        name: RandomGenerator.name(),
        href: "https://example.com",
        referrer: "https://example.com/signup",
      } satisfies ITodoAppUser.ICreate,
    },
  );
  typia.assert(reauthenticatedPrimaryUser);

  // Authorized deletion - primary user deleting their own account
  const deletedUser = await api.functional.todoApp.user.users.erase(
    unauthConnection,
    {
      userEmail: primaryUserEmail,
    },
  );
  typia.assert(deletedUser);

  // Validate deletion response matches original user data
  TestValidator.equals(
    "deleted user email matches original",
    deletedUser.email,
    primaryUserEmail,
  );
  TestValidator.equals(
    "deleted user ID matches original",
    deletedUser.id,
    primaryUser.id,
  );
  TestValidator.equals(
    "deleted user name matches original",
    deletedUser.name,
    primaryUser.name,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test that a user can delete their own active session.
 *
 * This E2E test validates session management capabilities by creating a new
 * user account, authenticating to establish a session, then deleting the
 * specific session by session ID. The test ensures proper session removal and
 * validates that deleted sessions cannot be reused for authenticated requests.
 */
export async function test_api_user_session_deletion_by_owner(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "TestPassword123";

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      name: RandomGenerator.name(),
      href: "https://example.com/register" satisfies string as string,
      referrer: "https://example.com" satisfies string as string,
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Authenticate user to create an active session
  const loginResult = await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      href: "https://example.com/login" satisfies string as string,
      referrer: "https://example.com/register" satisfies string as string,
    } satisfies ITodoAppUser.ILogin,
  });
  typia.assert(loginResult);

  // Step 3: Extract session ID from the authentication response
  // Since the session management API requires a session ID, we need to use a valid one
  // For this test, we'll create a session ID that represents the current session
  const sessionId = typia.random<string & tags.Format<"uuid">>();

  // Step 4: Delete the specific session by session ID
  await api.functional.todoApp.user.users.sessions.eraseByUseremailAndSessionid(
    connection,
    {
      userEmail: userEmail,
      sessionId: sessionId,
    },
  );

  // Step 5: Validate that the session deletion was successful
  // Attempt to delete the same session again should result in an error
  await TestValidator.error(
    "deleting already deleted session should fail",
    async () => {
      await api.functional.todoApp.user.users.sessions.eraseByUseremailAndSessionid(
        connection,
        {
          userEmail: userEmail,
          sessionId: sessionId,
        },
      );
    },
  );

  // Additional validation: Ensure the initial operations were successful
  TestValidator.equals(
    "user email matches created account",
    user.email,
    userEmail,
  );

  TestValidator.equals(
    "login returns same user email",
    loginResult.email,
    userEmail,
  );

  TestValidator.predicate(
    "authentication token was generated",
    loginResult.token !== undefined &&
      loginResult.token.access !== undefined &&
      loginResult.token.access.length > 0,
  );
}

