import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test pagination behavior with various page sizes and limits.
 *
 * Creates sufficient todo items to require multiple pages, then tests
 * pagination with different limit values (including maximum limit of 100).
 * Validates that pagination metadata is correct and page navigation works as
 * expected.
 */
export async function test_api_todo_search_pagination_limits(
  connection: api.IConnection,
) {
  // Step 1: Create authenticated user account
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "password123",
      name: RandomGenerator.name(),
      href: "https://example.com",
      referrer: "https://example.com/referrer",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create large number of todo items for pagination testing
  const todoCount = 150; // More than maximum page limit to test pagination
  const createdTodos: ITodoAppTodo[] = [];

  for (let i = 0; i < todoCount; i++) {
    const todo = await api.functional.todoApp.user.todos.create(connection, {
      body: {
        text: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 3,
          wordMax: 8,
        }),
        completed: i % 3 === 0, // Mix completed and incomplete todos
      } satisfies ITodoAppTodo.ICreate,
    });
    typia.assert(todo);
    createdTodos.push(todo);
  }

  // Step 3: Test pagination with default limit (no limit specified)
  const defaultPage = await api.functional.todoApp.user.todos.index(
    connection,
    {
      body: {
        page: 1,
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(defaultPage);

  TestValidator.predicate(
    "default page should return todos",
    defaultPage.data.length > 0,
  );
  TestValidator.predicate(
    "default page should have valid pagination",
    defaultPage.pagination.records >= todoCount,
  );

  // Step 4: Test pagination with maximum limit of 100
  const maxLimitPage = await api.functional.todoApp.user.todos.index(
    connection,
    {
      body: {
        page: 1,
        limit: 100,
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(maxLimitPage);

  TestValidator.equals(
    "maximum limit page should have correct item count",
    maxLimitPage.data.length,
    100,
  );
  TestValidator.equals(
    "maximum limit should be respected",
    maxLimitPage.pagination.limit,
    100,
  );
  TestValidator.predicate(
    "total records should match created todos",
    maxLimitPage.pagination.records >= todoCount,
  );

  // Step 5: Test pagination with smaller limits
  const testLimits = [10, 25, 50] as const;

  for (const limit of testLimits) {
    const limitedPage = await api.functional.todoApp.user.todos.index(
      connection,
      {
        body: {
          page: 1,
          limit: limit,
        } satisfies ITodoAppTodo.IRequest,
      },
    );
    typia.assert(limitedPage);

    TestValidator.equals(
      `limit ${limit} should be respected`,
      limitedPage.data.length,
      limit,
    );
    TestValidator.equals(
      `pagination limit should match requested ${limit}`,
      limitedPage.pagination.limit,
      limit,
    );
  }

  // Step 6: Test page navigation
  const firstPage = await api.functional.todoApp.user.todos.index(connection, {
    body: {
      page: 1,
      limit: 25,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(firstPage);

  const secondPage = await api.functional.todoApp.user.todos.index(connection, {
    body: {
      page: 2,
      limit: 25,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(secondPage);

  TestValidator.notEquals(
    "first and second page should have different data",
    firstPage.data,
    secondPage.data,
  );
  TestValidator.predicate(
    "pagination metadata should be consistent",
    firstPage.pagination.records === secondPage.pagination.records &&
      firstPage.pagination.limit === secondPage.pagination.limit,
  );

  // Step 7: Test pagination metadata calculations
  const testPage = await api.functional.todoApp.user.todos.index(connection, {
    body: {
      page: 1,
      limit: 30,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(testPage);

  const expectedPages = Math.ceil(testPage.pagination.records / 30);
  TestValidator.equals(
    "total pages calculation should be correct",
    testPage.pagination.pages,
    expectedPages,
  );
  TestValidator.equals(
    "current page should be correct",
    testPage.pagination.current,
    1,
  );

  // Step 8: Test edge case - request page beyond total pages
  const lastPage = await api.functional.todoApp.user.todos.index(connection, {
    body: {
      page: testPage.pagination.pages + 1, // Request page beyond total
      limit: 30,
    } satisfies ITodoAppTodo.IRequest,
  });
  typia.assert(lastPage);

  TestValidator.predicate(
    "requesting page beyond total should return empty data",
    lastPage.data.length === 0,
  );
  TestValidator.equals(
    "current page should reflect requested page even if empty",
    lastPage.pagination.current,
    testPage.pagination.pages + 1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test successful token refresh workflow for authenticated users with valid
 * refresh tokens.
 *
 * This test validates the complete authentication lifecycle: user registration,
 * initial login, and token refresh operation. It ensures that refresh tokens
 * properly rotate access tokens while maintaining session continuity and
 * preventing token reuse vulnerabilities.
 */
export async function test_api_user_token_refresh_valid_session(
  connection: api.IConnection,
) {
  // Generate realistic test data
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "TestPassword123";
  const userName = RandomGenerator.name();
  const baseUrl = "https://example.com";

  // Step 1: Create a new user account
  const createdUser = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      name: userName,
      href: baseUrl,
      referrer: baseUrl,
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(createdUser);

  // Step 2: Authenticate user to obtain initial tokens
  const authenticatedUser = await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      href: baseUrl,
      referrer: baseUrl,
    } satisfies ITodoAppUser.ILogin,
  });
  typia.assert(authenticatedUser);

  // Validate initial token structure
  TestValidator.equals(
    "user ID remains consistent",
    createdUser.id,
    authenticatedUser.id,
  );
  TestValidator.equals(
    "user email remains consistent",
    createdUser.email,
    authenticatedUser.email,
  );
  TestValidator.equals(
    "user name remains consistent",
    createdUser.name,
    authenticatedUser.name,
  );

  // Store original tokens for comparison
  const originalAccessToken = authenticatedUser.token.access;
  const originalRefreshToken = authenticatedUser.token.refresh;
  const originalExpiredAt = authenticatedUser.token.expired_at;
  const originalRefreshableUntil = authenticatedUser.token.refreshable_until;

  // Step 3: Refresh tokens using the refresh endpoint
  const refreshedUser = await api.functional.auth.user.refresh(connection, {
    body: {
      refresh_token: originalRefreshToken,
    } satisfies ITodoAppUser.IRefresh,
  });
  typia.assert(refreshedUser);

  // Step 4: Validate token rotation and session continuity
  TestValidator.equals(
    "user ID remains consistent after refresh",
    authenticatedUser.id,
    refreshedUser.id,
  );
  TestValidator.equals(
    "user email remains consistent after refresh",
    authenticatedUser.email,
    refreshedUser.email,
  );
  TestValidator.equals(
    "user name remains consistent after refresh",
    authenticatedUser.name,
    refreshedUser.name,
  );

  // Validate token rotation (new tokens should differ from original)
  TestValidator.notEquals(
    "access token should be rotated",
    originalAccessToken,
    refreshedUser.token.access,
  );
  TestValidator.notEquals(
    "refresh token should be rotated",
    originalRefreshToken,
    refreshedUser.token.refresh,
  );

  // Validate token structure
  TestValidator.predicate(
    "new access token should not be empty",
    refreshedUser.token.access.length > 0,
  );
  TestValidator.predicate(
    "new refresh token should not be empty",
    refreshedUser.token.refresh.length > 0,
  );

  // Validate expiration timestamps
  TestValidator.predicate("new expired_at should be a valid date-time", () => {
    const expiredAtDate = new Date(refreshedUser.token.expired_at);
    return !isNaN(expiredAtDate.getTime());
  });

  TestValidator.predicate(
    "new refreshable_until should be a valid date-time",
    () => {
      const refreshableUntilDate = new Date(
        refreshedUser.token.refreshable_until,
      );
      return !isNaN(refreshableUntilDate.getTime());
    },
  );

  // Validate that new expiration timestamps are in the future
  const currentTime = new Date();
  const newExpiredAt = new Date(refreshedUser.token.expired_at);
  const newRefreshableUntil = new Date(refreshedUser.token.refreshable_until);

  TestValidator.predicate(
    "new expired_at should be in the future",
    newExpiredAt > currentTime,
  );
  TestValidator.predicate(
    "new refreshable_until should be in the future",
    newRefreshableUntil > currentTime,
  );

  // Additional validation: Ensure the refreshed tokens can be used for subsequent operations
  // This demonstrates that the new tokens are functional
  TestValidator.predicate(
    "refreshed access token should be valid JWT format",
    () => {
      const tokenParts = refreshedUser.token.access.split(".");
      return tokenParts.length === 3;
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test token refresh failure scenario with expired refresh tokens.
 *
 * This test validates the security mechanism that prevents expired refresh
 * tokens from obtaining new access tokens. The test establishes user
 * authentication context, obtains tokens, and attempts refresh operation with
 * tokens that should be expired to verify proper error handling and security
 * enforcement.
 */
export async function test_api_user_token_refresh_expired_token(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account for authentication testing
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "TestPassword123";

  const createdUser = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      name: RandomGenerator.name(),
      href: "https://todoapp.example.com/register",
      referrer: "https://todoapp.example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(createdUser);

  // Step 2: Obtain initial tokens through login
  const initialTokens = await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      href: "https://todoapp.example.com/login",
      referrer: "https://todoapp.example.com",
    } satisfies ITodoAppUser.ILogin,
  });
  typia.assert(initialTokens);

  // Step 3: Extract token expiration information for validation
  const refreshExpiration = new Date(initialTokens.token.refreshable_until);
  const accessExpiration = new Date(initialTokens.token.expired_at);

  // Validate that tokens have expiration times set
  TestValidator.predicate(
    "refresh token has future expiration time",
    refreshExpiration > new Date(),
  );

  TestValidator.predicate(
    "access token has future expiration time",
    accessExpiration > new Date(),
  );

  // Step 4: Attempt to refresh with the same token immediately - should work
  // This validates that the refresh token is initially valid
  const refreshedTokens = await api.functional.auth.user.refresh(connection, {
    body: {
      refresh_token: initialTokens.token.refresh,
    } satisfies ITodoAppUser.IRefresh,
  });
  typia.assert(refreshedTokens);

  // Step 5: Now attempt to refresh with the original (now invalid) token
  // After a successful refresh, the original refresh token should be invalidated
  await TestValidator.error(
    "refresh should fail with previously used token",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: initialTokens.token.refresh,
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );

  // Step 6: Validate that the new tokens are different from the original ones
  TestValidator.notEquals(
    "new access token should differ from original",
    refreshedTokens.token.access,
    initialTokens.token.access,
  );

  TestValidator.notEquals(
    "new refresh token should differ from original",
    refreshedTokens.token.refresh,
    initialTokens.token.refresh,
  );

  // Step 7: Additional security validation
  // The new tokens should have updated expiration times
  const newRefreshExpiration = new Date(
    refreshedTokens.token.refreshable_until,
  );
  const newAccessExpiration = new Date(refreshedTokens.token.expired_at);

  TestValidator.predicate(
    "new refresh token has future expiration time",
    newRefreshExpiration > new Date(),
  );

  TestValidator.predicate(
    "new access token has future expiration time",
    newAccessExpiration > new Date(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test token refresh failure scenario with invalid or tampered refresh tokens.
 *
 * This test validates security measures against token manipulation and
 * unauthorized access attempts. It establishes proper authentication context,
 * then attempts refresh with intentionally corrupted tokens to verify robust
 * validation and error handling. Validates that the system detects token
 * integrity violations and prevents security breaches.
 */
export async function test_api_user_token_refresh_invalid_token(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account for authentication testing
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "TestPassword123";

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      name: RandomGenerator.name(),
      href: "https://example.com/app",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Login to obtain valid tokens
  const loginResult = await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      href: "https://example.com/app",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ILogin,
  });
  typia.assert(loginResult);

  const validRefreshToken = loginResult.token.refresh;

  // Step 3: Test empty string refresh token
  await TestValidator.error("empty refresh token should fail", async () => {
    await api.functional.auth.user.refresh(connection, {
      body: {
        refresh_token: "",
      } satisfies ITodoAppUser.IRefresh,
    });
  });

  // Step 4: Test random string as refresh token
  await TestValidator.error(
    "random string refresh token should fail",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: RandomGenerator.alphaNumeric(32),
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );

  // Step 5: Test malformed JWT-like string
  await TestValidator.error(
    "malformed JWT refresh token should fail",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token:
            "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.invalid.payload.signature",
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );

  // Step 6: Test tampered valid refresh token with robust logic
  if (validRefreshToken && validRefreshToken.length > 5) {
    const midPoint = Math.floor(validRefreshToken.length / 2);
    const tamperedToken =
      validRefreshToken.substring(0, midPoint) +
      "TAMPERED" +
      validRefreshToken.substring(midPoint);

    await TestValidator.error(
      "tampered refresh token should fail",
      async () => {
        await api.functional.auth.user.refresh(connection, {
          body: {
            refresh_token: tamperedToken,
          } satisfies ITodoAppUser.IRefresh,
        });
      },
    );
  }

  // Step 7: Test numeric string as refresh token
  await TestValidator.error(
    "numeric string refresh token should fail",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: "12345678901234567890123456789012",
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );

  // Step 8: Verify valid refresh token still works (positive control)
  const refreshResult = await api.functional.auth.user.refresh(connection, {
    body: {
      refresh_token: validRefreshToken,
    } satisfies ITodoAppUser.IRefresh,
  });
  typia.assert(refreshResult);

  TestValidator.equals(
    "valid refresh should return new tokens with same user ID",
    refreshResult.id,
    user.id,
  );
}

